import type {JournalDeData} from '@/components/JournalArticleDe';
export const journalDe:Record<string,JournalDeData>={
"regata-storica-2026":{slug:"regata-storica-2026",eventDate:"6. SEPTEMBER 2026",title:"Regata Storica Venedig 2026",category:"Veranstaltungen",description:"Historischer Wasserumzug, venezianisches Rudern und Regatten auf dem Canal Grande am Sonntag, 6. September 2026.",lead:"Am Sonntag, 6. September 2026, feiert Venedig eines seiner eindrucksvollsten und traditionsreichsten Ereignisse: die Regata Storica. Jedes Jahr am ersten Sonntag im September wird der Canal Grande zur Bühne für Geschichte, Voga alla Veneta, historische Boote und sportliche Wettkämpfe.",image:"/images/journal-regata-storica-2026.webp",imageAlt:"Historische Boote bei der Regata Storica auf dem Canal Grande in Venedig",sections:[["Der historische Wasserumzug","Um 15:30 Uhr beginnt der Corteo Storico-Sportivo: historische Boote mit Figuren in Kostümen, Gondeln und Boote der venezianischen Rudervereine ziehen vom Markusbecken über den Canal Grande, Rialto und den Bahnhof bis zurück nach Ca’ Foscari. Der historische Teil erinnert an den Empfang Caterina Cornaros im Jahr 1489."],["Die Regatten auf dem Canal Grande","Ab 16:00 Uhr folgen die Rennen. Zu den wichtigsten gehören die Caorline mit sechs Riemen um 17:10 Uhr, die Frauenregatta auf zweiriemigen Mascarete um 17:40 Uhr und die Gondolini-Regatta um 18:10 Uhr. Hinzu kommt die internationale Universitäts-Ruderchallenge auf Galeonen mit acht Riemen."],["Wo kann man die Regata Storica sehen?","Markusbecken und Punta della Dogana, Rialto, der Bereich um San Marcuola sowie Ca’ Foscari gehören zu den interessantesten Abschnitten. Entlang des Canal Grande füllen sich die Ufer früh: Wer einen guten Platz möchte, sollte deutlich vor Beginn ankommen."],["Achtung bei den Verkehrsmitteln","Am 6. September wird der ACTV-Schiffsverkehr am Nachmittag geändert oder zeitweise unterbrochen. Nach den offiziellen Angaben gelten Einschränkungen ungefähr zwischen 14:00 und 19:30 Uhr; auf dem Canal Grande ist die Schifffahrt etwa von 15:00 bis 19:30 Uhr ausgesetzt. Von Marghera empfehlen wir Bus oder Zug und anschließend Wege zu Fuß einzuplanen."],["Warum sich die Regata Storica lohnt","Die Regata Storica ist nicht nur eine Show für Besucher. Die Voga alla Veneta ist eine lebendige Tradition, und dieser Tag ist einer der Höhepunkte des venezianischen Ruderkalenders. Historische Inszenierung, Sport und lokale Leidenschaft treffen hier auf demselben Wasser zusammen."],["Praktische Informationen","Datum: Sonntag, 6. September 2026. Ort: Canal Grande, Venedig. Historischer Umzug ab etwa 15:30 Uhr, Regatten ab 16:00 Uhr. Programm und Verkehrsmaßnahmen können sich ändern: prüfen Sie kurz vor dem Besuch immer die offizielle Website."]],tip:"Fahren Sie früh mit Bus oder Zug nach Venedig, wählen Sie Ihren Abschnitt am Canal Grande im Voraus und planen Sie die Rückfahrt, bevor die stärksten Besucherströme beginnen.",official:["Offizielle Website der Regata Storica","https://www.regatastoricavenezia.it/en/"]},
"vogalonga-2027":{slug:"vogalonga-2027",title:"Vogalonga in Venedig: das große Ruderfest der Lagune",category:"Veranstaltungen",eventDate:"MAI 2027",description:"30 Kilometer ohne Wettkampfcharakter durch Lagune, Inseln und Canal Grande: die Vogalonga feiert Venedig, das Rudern und eine nachhaltigere Beziehung zum Wasser.",lead:"Die Vogalonga gehört zu den Veranstaltungen, bei denen man Venedig besonders unmittelbar erlebt. Tausende Ruderer und Boote aus vielen Ländern treffen sich in der Lagune zu einer langen, nicht wettkampforientierten Fahrt, die der Stadt, ihren Inseln und der Tradition des Ruderns gewidmet ist.",image:"/images/journal-vogalonga-2027-cover.webp",cardImage:"/images/journal-vogalonga-2027-card.webp",imageAlt:"Zahlreiche Ruderboote während der Vogalonga in der Lagune von Venedig",sections:[["Was ist die Vogalonga?","Die Vogalonga ist ein nicht wettkampforientiertes Ruderevent und versteht sich als Liebeserklärung an Venedig, seine Lagune, seine Inseln und die traditionelle Fortbewegung mit Ruderbooten. Der ursprüngliche Gedanke bleibt bis heute erhalten: Natur und Kultur der Stadt bewusster zu respektieren."],["30 Kilometer zwischen Lagune, Inseln und Canal Grande","Die historische Strecke ist etwa 30 Kilometer lang und führt durch die venezianische Lagune, an Inseln vorbei und schließlich in den Canal Grande. Gerade die Mischung aus Landschaft, Stadt und Wasser macht die Veranstaltung auch für Zuschauer außergewöhnlich."],["Tausende Ruderer, Tausende Boote","Die offizielle Website nennt für die Veranstaltung rund 8.000 Ruderer und etwa 2.000 Boote. Zugelassen sind Ruderboote unterschiedlicher Art und Größe: Entscheidend ist nicht die Geschwindigkeit, sondern die gemeinsame Teilnahme."],["Warum die Vogalonga zu Venedig passt","Die Veranstaltung fördert traditionelle und nachhaltigere Formen der Fortbewegung auf dem Wasser und erinnert zugleich daran, wie stark Venedig unter dem Wellenschlag motorisierter Boote leidet. Damit ist sie Sportfest, kulturelle Tradition und Botschaft für den Schutz der Stadt zugleich."],["Wo kann man zuschauen?","Wer nicht selbst rudert, kann die Atmosphäre an verschiedenen Punkten der Strecke erleben. Besonders eindrucksvoll ist der Einzug der vielen Boote in den Canal Grande. Wegen möglicher Änderungen bei Verkehr und Navigation sollte man am Veranstaltungstag die offiziellen Hinweise prüfen."],["Ausgabe 2027","Die nächste Ausgabe ist für Mai 2027 vorgesehen; der genaue Termin soll auf der offiziellen Website bestätigt werden. Fahrplanänderungen, Anmeldungen und organisatorische Hinweise werden dort veröffentlicht, sobald sie verfügbar sind."]],tip:"Wenn Sie die Vogalonga erleben möchten, planen Sie den Tag nicht zu eng. Fahren Sie früh nach Venedig, wählen Sie einen Abschnitt der Strecke und verbinden Sie die Veranstaltung mit einem Spaziergang abseits der Hauptachsen.",official:["Vogalonga – offizielle Website","https://vogalonga.com/en/"]},
"carnevale-di-venezia":{slug:"carnevale-di-venezia",eventDate:"23. JANUAR – 9. FEBRUAR 2027",title:"Karneval in Venedig 2027",category:"Veranstaltungen",description:"Vom 23. Januar bis 9. Februar 2027 verwandeln Masken, Umzüge und Veranstaltungen Venedig in eine große Bühne.",lead:"Der venezianische Karneval ist weit mehr als der Markusplatz. Veranstaltungen verteilen sich über Gassen, Plätze, Paläste, Inseln und das Festland.",image:"/images/journal-carnevale.webp",imageAlt:"Karnevalsmasken in Venedig",sections:[["Eine jahrhundertealte Tradition", "Der Karneval von Venedig blickt auf eine lange Geschichte zurück. Heute verbinden sich historische Masken, Straßenkunst, Wasserumzüge und Kulturveranstaltungen."], ["Den Tag gut planen", "Prüfen Sie vorab das offizielle Programm und wählen Sie wenige Höhepunkte. An Wochenenden und in den letzten Karnevalstagen kann es im Zentrum sehr voll werden."], ["Karneval mit Kindern", "Masken und Aufführungen machen auch Familien Spaß. Planen Sie Pausen ein und vermeiden Sie einen zu starren Zeitplan."]],tip:"Lassen Sie das Auto an der Unterkunft und fahren Sie mit öffentlichen Verkehrsmitteln nach Venedig.",official:['Offizielles Karnevalsprogramm','https://carnevale.venezia.it/en/']},
"festa-del-redentore":{slug:"festa-del-redentore",eventDate:"17. JULI 2027",title:"Festa del Redentore 2027",category:"Traditionen",description:"Am Samstag, 17. Juli 2027, erreicht eines der wichtigsten venezianischen Sommerfeste mit Booten und Feuerwerk seinen Höhepunkt.",lead:"Das Redentore-Fest verbindet religiöse Tradition, gemeinsames Feiern und eines der eindrucksvollsten Feuerwerke des venezianischen Sommers.",image:"/images/journal-redentore.webp",imageAlt:"Feuerwerk beim Festa del Redentore in Venedig",sections:[["Eine venezianische Tradition", "Das Fest erinnert an das Ende einer Pestepidemie im 16. Jahrhundert und ist eng mit der Redentore-Kirche auf Giudecca verbunden."], ["Der Samstagabend", "Viele Venezianer feiern auf Booten oder entlang der Ufer. Höhepunkt ist das große Feuerwerk über dem Bacino di San Marco."], ["Praktisch planen", "An diesem Wochenende sind Stadt und Verkehr besonders stark ausgelastet. Informieren Sie sich frühzeitig über Sonderfahrpläne und Zugänge."]],tip:"Planen Sie die Rückfahrt im Voraus und prüfen Sie die Sonderfahrpläne von ACTV.",official:['Stadt Venedig – offizielle Informationen','https://www.comune.venezia.it/en']},
"natale-capodanno-venezia":{slug:"natale-capodanno-venezia",title:"Weihnachten und Silvester in Venedig",category:"Jahreszeiten",description:"Lichter, Winterstimmung und besondere Feiertage zwischen Lagune und historischen Plätzen.",lead:"Im Winter zeigt Venedig eine ruhigere, stimmungsvolle Seite. Weihnachten und Silvester verbinden festliche Beleuchtung, Kultur und besondere Veranstaltungen.",image:"/images/journal-natale-capodanno.webp",imageAlt:"Weihnachtliche Atmosphäre in Venedig",sections:[["Venedig im Winter", "Kühlere Temperaturen und kürzere Tage verändern den Rhythmus der Stadt. Warme Kleidung und flexible Planung sind wichtig."], ["Weihnachtszeit", "Museen, Kirchen, Konzerte und saisonale Veranstaltungen bieten viele Möglichkeiten auch bei schlechtem Wetter."], ["Silvester", "Rund um den Jahreswechsel können Plätze und Verkehrsmittel sehr voll werden. Prüfen Sie das offizielle Veranstaltungsprogramm und die Rückfahrt."]],tip:"Buchen Sie Restaurants und besondere Erlebnisse für die Feiertage möglichst frühzeitig.",official:['Venezia Unica – offizielle Informationen','https://www.veneziaunica.it/en']},
"mostra-del-cinema":{slug:"mostra-del-cinema",eventDate:"2.–12. SEPTEMBER 2026",title:"Filmfestspiele von Venedig 2026",category:"Kunst & Kultur",description:"Die 83. Filmfestspiele von Venedig finden vom 2. bis 12. September 2026 am Lido statt – mit Premieren, öffentlichen Vorführungen, rotem Teppich und Venice Immersive.",lead:"Vom 2. bis 12. September 2026 wird der Lido di Venezia wieder zu einem der wichtigsten Treffpunkte der internationalen Filmwelt. Die 83. Mostra Internazionale d’Arte Cinematografica wird von La Biennale di Venezia organisiert und von Alberto Barbera geleitet.",image:"/images/journal-mostra-cinema.webp",imageAlt:"Filmfestspiele von Venedig am Lido",sections:[["Die Ausgabe 2026","Die 83. Filmfestspiele finden elf Tage lang am Lido statt. Das Herz der Veranstaltung liegt rund um den Palazzo del Cinema, den Palazzo del Casinò, die Sala Darsena und weitere Spielstätten der Biennale."],["Auch ohne Akkreditierung ins Kino","Die Mostra ist nicht nur für Fachpublikum und eingeladene Gäste gedacht. Viele Vorführungen sind für das normale Publikum mit Online-Ticket zugänglich; einzelne Galapremieren bleiben hingegen Einladungsveranstaltungen. Prüfen Sie deshalb immer den offiziellen Tagesplan."],["Venice Immersive","Auf der Isola del Lazzaretto Vecchio gegenüber der Riva di Corinto zeigt Venice Immersive 68 XR-Projekte aus 26 Ländern – von Virtual und Mixed Reality bis zu immersiven Installationen und virtuellen Welten."],["Roter Teppich und besondere Momente","Zum Auftakt am 2. September wird George Clooney mit dem Goldenen Löwen für sein Lebenswerk geehrt. Der rote Teppich und die Gästelisten ändern sich täglich; wer die Atmosphäre erleben möchte, sollte den offiziellen Kalender kurz vor dem Besuch prüfen."],["So kommen Sie vom Festland zum Lido","Von Marghera fahren Sie am einfachsten mit Bus oder Zug nach Venedig und anschließend mit dem Vaporetto zum Lido. Während der wichtigsten Festivaltage lohnt es sich, für Umstiege und Warteschlangen mehr Zeit einzuplanen."],["Ein besonders volles Wochenende","Am Sonntag, 6. September, findet zusätzlich die Regata Storica auf dem Canal Grande statt. Wenn Sie beide Ereignisse erleben möchten, planen Sie die Wege sorgfältig und rechnen Sie mit Änderungen im Schiffsverkehr."]],tip:"Wenn Sie die Mostra erleben möchten, ohne den ganzen Tag einem starren Programm zu folgen, wählen Sie eine öffentliche Vorführung, verbringen Sie Zeit am Lido und kontrollieren Sie am selben Tag noch einmal Programm und Verkehr.",official:["La Biennale – Cinema 2026","https://www.labiennale.org/en/cinema/2026"]},
"homo-faber-2026":{slug:"homo-faber-2026",eventDate:"1.–30. SEPTEMBER 2026",title:"Homo Faber 2026: An Island of Light",category:"Kunst & Kultur",description:"Vom 1. bis 30. September verwandelt Homo Faber die Fondazione Giorgio Cini auf San Giorgio Maggiore in eine internationale Bühne für zeitgenössisches Kunsthandwerk.",lead:"Homo Faber 2026: An Island of Light lädt einen ganzen Monat lang dazu ein, die Beziehung zwischen Licht, Material und menschlicher Hand zu entdecken. Die vierte Ausgabe der Biennale wird von Es Devlin künstlerisch geleitet und findet in der Fondazione Giorgio Cini auf San Giorgio Maggiore statt.",image:"/images/journal-homo-faber-2026-cover.webp",cardImage:"/images/journal-homo-faber-2026-card.webp",imageAlt:"Offizielles Motiv von Homo Faber 2026 An Island of Light",posterHero:true,sections:[["Was ist Homo Faber?","Homo Faber ist eine internationale Biennale, die herausragendes zeitgenössisches Kunsthandwerk sichtbar macht. 2026 stehen Hunderte handgefertigte Objekte von Kunsthandwerkern aus aller Welt im Mittelpunkt."],["An Island of Light","Die Ausgabe 2026 untersucht unter der künstlerischen Leitung von Es Devlin das Zusammenspiel von Licht, Materialien und Handwerk. Fünfzehn immersive Installationen führen durch die historischen Räume und Gärten der Fondazione Giorgio Cini."],["Mehr als eine Ausstellung","Zum Programm gehören Live-Demonstrationen, Mitmach-Workshops, kulinarische Erlebnisse und besondere Führungen. Dadurch lässt sich nicht nur das fertige Objekt betrachten, sondern auch der Prozess und das Können dahinter besser verstehen."],["Ein besonderer Ort: San Giorgio Maggiore","Die Insel liegt nur wenige Minuten mit dem Vaporetto vom Markusplatz entfernt, wirkt aber deutlich ruhiger. Der Besuch lässt sich gut mit der Basilika San Giorgio Maggiore und einem Blick auf das Becken von San Marco verbinden."],["Homo Faber in Città","Das Projekt reicht auch über San Giorgio hinaus. Während des Monats finden in Venedig weitere Ausstellungen und Initiativen statt, die Kunsthandwerk, Design, Materialien und lokale Meister miteinander verbinden."],["Praktische Informationen","Homo Faber 2026 läuft vom 1. bis 30. September in der Fondazione Giorgio Cini. Öffnungszeiten, Tickets, Workshops und Tagesprogramm können variieren: prüfen Sie vor dem Besuch die offizielle Website."]],tip:"Planen Sie mindestens einen halben Tag für San Giorgio ein. Wenn Sie Kunst, Design und handwerkliche Prozesse mögen, lohnt es sich, vorab auch das Tagesprogramm mit Vorführungen und Workshops anzusehen.",official:["Homo Faber 2026 – offizielle Website","https://www.homofaber.com/en/biennial/homofaber-2026"]},
"biennale-di-venezia":{slug:"biennale-di-venezia",eventDate:"9. MAI – 22. NOVEMBER 2026",title:"Biennale Arte Venedig 2026",category:"Kunst & Kultur",description:"Die 61. Internationale Kunstausstellung In Minor Keys läuft vom 9. Mai bis 22. November 2026 zwischen Giardini, Arsenale, Forte Marghera und weiteren Orten in Venedig.",lead:"Die Biennale verwandelt Venedig in eine internationale Bühne für zeitgenössische Kunst und Architektur – von den Giardini und dem Arsenale bis zu Ausstellungen in der ganzen Stadt.",image:"/images/journal-biennale.webp",imageAlt:"Ausstellung der Biennale di Venezia",sections:[["Giardini und Arsenale", "Die beiden Hauptbereiche sind umfangreich. Wer beide intensiv sehen möchte, sollte genügend Zeit einplanen."], ["Ausstellungen in der Stadt", "Zusätzlich zu den Hauptstandorten finden zahlreiche Projekte und Begleitausstellungen in Palästen, Kirchen und anderen Räumen statt."], ["Tickets und Termine", "Öffnungszeiten und Programme ändern sich je nach Ausgabe. Nutzen Sie die offizielle Website für aktuelle Informationen."]],tip:"Versuchen Sie nicht, alles an einem Tag zu sehen: Weniger Stationen und mehr Zeit pro Ausstellung sind meist die bessere Wahl.",official:['La Biennale – offizielle Website','https://www.labiennale.org/en/art/2026']},
"venezia-con-bambini":{slug:"venezia-con-bambini",title:"Venedig mit Kindern",category:"Familien",description:"Venedig als Familie entspannt und mit realistischem Tempo entdecken.",lead:"Mit Kindern funktioniert Venedig am besten ohne überfüllten Tagesplan: kurze Etappen, Pausen auf Plätzen und Fahrten mit dem Vaporetto machen den Besuch abwechslungsreich.",image:"/images/venezia-bambini-campo-nuova.webp",imageAlt:"Familie mit Kindern auf einem Platz in Venedig",sections:[["Tempo reduzieren", "Brücken und lange Wege können anstrengend sein. Planen Sie weniger Sehenswürdigkeiten und mehr Pausen."], ["Vaporetto als Erlebnis", "Eine Fahrt auf dem Canal Grande ist Verkehrsmittel und Erlebnis zugleich."], ["Freie Plätze nutzen", "Campi bieten Raum für eine Pause abseits enger Gassen. Achten Sie trotzdem immer auf Kanäle und Wasserzugänge."]],tip:"Nehmen Sie Wasser, kleine Snacks und möglichst leichtes Gepäck mit – besonders mit Kinderwagen.",official:['MUVE – Museen in Venedig','https://msn.visitmuve.it/en/home/']},
"venezia-con-il-cane":{slug:"venezia-con-il-cane",title:"Venedig mit Hund",category:"Haustiere",description:"Praktische Tipps für einen entspannten Besuch mit Ihrem Vierbeiner.",lead:"Venedig lässt sich auch mit Hund entdecken. Entscheidend sind Tageszeit, Temperaturen, Menschenmengen und die Regeln der jeweiligen Verkehrsmittel und Sehenswürdigkeiten.",image:"/images/journal-venezia-cane.webp",imageAlt:"Hund bei einem Spaziergang in Venedig",sections:[["Ruhige Zeiten wählen", "Früher Morgen und weniger überlaufene Viertel sind für Hunde oft angenehmer."], ["Wasser und Pausen", "Im Sommer können Steinflächen sehr heiß werden. Sorgen Sie für Wasser und regelmäßige Pausen."], ["Regeln prüfen", "Für öffentliche Verkehrsmittel, Museen und einzelne Attraktionen gelten unterschiedliche Bestimmungen."]],tip:"Planen Sie Spaziergänge eher in ruhigen Vierteln und prüfen Sie die ACTV-Regeln vor der Fahrt.",official:['AVM/ACTV – Verkehrsinformationen','https://avm.avmspa.it/en/content/venice-urban-services-0']},
"acqua-alta-a-venezia":{slug:"acqua-alta-a-venezia",title:"Acqua alta in Venedig",category:"Praktische Tipps",description:"Was Hochwasser bedeutet und wie Sie Ihren Besuch flexibel planen.",lead:"Acqua alta ist ein zeitweiliges Hochwasserphänomen in der Lagune. Es betrifft je nach Höhe unterschiedliche Bereiche und bedeutet nicht automatisch, dass ein ganzer Besuch ausfallen muss.",image:"/images/journal-acqua-alta.webp",imageAlt:"Hochwasser auf einem Platz in Venedig",sections:[["Was passiert", "Bei erhöhtem Wasserstand können tiefer gelegene Bereiche zeitweise überflutet werden."], ["Aktuelle Prognosen", "Prüfen Sie vor und während des Besuchs die offiziellen Pegel- und Wetterinformationen."], ["Flexibel bleiben", "Passen Sie Route und Uhrzeit an. Häufig verändert sich die Situation innerhalb weniger Stunden."]],tip:"Verlassen Sie sich bei Hochwasser ausschließlich auf aktuelle offizielle Prognosen, nicht auf alte Erfahrungswerte.",official:['Stadt Venedig – Gezeitenvorhersage','https://www.comune.venezia.it/en/content/tide-forecasting-and-reporting-centre']},
"dove-parcheggiare-venezia":{slug:"dove-parcheggiare-venezia",title:"Parken für einen Besuch in Venedig",category:"Praktische Tipps",description:"Warum es oft einfacher ist, das Auto in Marghera stehen zu lassen.",lead:"In der historischen Altstadt von Venedig gibt es keinen Autoverkehr. Wer mit dem Auto anreist, muss es vor dem historischen Zentrum abstellen.",image:"/images/journal-parcheggi-venezia.webp",imageAlt:"Parkmöglichkeiten vor dem historischen Zentrum von Venedig",sections:[["Wo Autos enden", "Piazzale Roma und Tronchetto sind die wichtigsten Zufahrtspunkte für Fahrzeuge vor der Altstadt."], ["Bequemer von Marghera", "Unsere Gäste können den privaten Parkplatz der Unterkunft nutzen und Venedig mit öffentlichen Verkehrsmitteln erreichen."], ["Vorab prüfen", "Öffentliche Parkpreise und Verfügbarkeit können sich ändern. Prüfen Sie aktuelle Bedingungen direkt beim Betreiber."]],tip:"Nutzen Sie den kostenlosen privaten Parkplatz der Unterkunft und fahren Sie ohne Parkplatzsuche nach Venedig.",official:['AVM – städtische Garage','https://avm.avmspa.it/it/content/autorimessa-comunale-1']},
"spritz-veneziano":{slug:"spritz-veneziano",title:"Der venezianische Spritz",category:"Essen & Trinken",description:"Ein Aperitif, der fest zur venezianischen Alltagskultur gehört.",lead:"Der Spritz ist in Venedig mehr als ein Getränk: Er gehört zum Ritual des Aperitivo und wird häufig mit kleinen Snacks oder Cicchetti kombiniert.",image:"/images/journal-spritz.webp",imageAlt:"Venezianischer Spritz beim Aperitivo",sections:[["Aperitivo-Kultur", "Der Spritz wird traditionell vor dem Essen oder am frühen Abend getrunken."], ["Verschiedene Varianten", "Je nach Bitter und Mischungsverhältnis unterscheiden sich Geschmack und Farbe."], ["Mit Maß genießen", "Wer Alkohol trinkt, sollte besonders bei anschließender Autofahrt verantwortungsvoll planen."]],tip:"Probieren Sie den Aperitivo in einem Bacaro abseits der größten Touristenströme und lassen Sie das Auto stehen.",official:['Aperol – offizielle Website','https://terrazza.aperol.com/en/']},
"cicchetti-veneziani":{slug:"cicchetti-veneziani",title:"Venezianische Cicchetti",category:"Essen & Trinken",description:"Kleine Häppchen, Bacari und eine genussvolle Art, Venedig kennenzulernen.",lead:"Cicchetti sind kleine venezianische Häppchen, die traditionell in Bacari angeboten werden. Sie eignen sich perfekt für mehrere kurze Stopps statt eines einzigen langen Essens.",image:"/images/journal-cicchetti.webp",imageAlt:"Auswahl venezianischer Cicchetti",sections:[["Was sind Cicchetti?", "Die Auswahl reicht von belegtem Brot bis zu Fisch-, Gemüse- und Fleischvarianten und ändert sich von Lokal zu Lokal."], ["Bacari entdecken", "Ein Bacaro ist eine traditionelle venezianische Weinbar. Besonders schön ist es, verschiedene Viertel und Lokale zu kombinieren."], ["Respektvoll genießen", "Vermeiden Sie es, Eingänge oder enge Gassen zu blockieren, und entsorgen Sie Abfälle korrekt."]],tip:"Bestellen Sie lieber wenige Cicchetti pro Stopp und probieren Sie mehrere Bacari.",official:undefined},
"buone-maniere-a-venezia":{slug:"buone-maniere-a-venezia",title:"Gute Umgangsformen in Venedig",category:"Respektvoll reisen",description:"Kleine Regeln, die helfen, eine außergewöhnliche und fragile Stadt zu respektieren.",lead:"Venedig ist keine Kulisse, sondern eine lebendige Stadt. Rücksicht auf Bewohner, Wege, Wasser und historische Orte macht den Aufenthalt für alle angenehmer.",image:"/images/journal-buone-maniere.webp",imageAlt:"Besucher in einer venezianischen Gasse",sections:[["Wege freihalten", "Bleiben Sie auf Brücken und in engen Gassen nicht in großen Gruppen stehen und blockieren Sie keine Hauseingänge."], ["Sauberkeit und Wasser", "Hinterlassen Sie keinen Müll und springen oder baden Sie nicht in den Kanälen."], ["Die Stadt als Wohnort respektieren", "Vermeiden Sie unnötigen Lärm, respektieren Sie private Bereiche und folgen Sie lokalen Hinweisen."]],tip:"Bewegen Sie sich neugierig, aber respektvoll: Venedig ist das Zuhause vieler Menschen.",official:['Stadt Venedig – offizielle Website','https://www.comune.venezia.it/en']},
};
